function openFinancialDayInspector(date){
  const month=date.slice(0,7),day=Number(date.slice(8,10)),s=spentDate(date),g={...dailyGoal(date),total:dayGoalForMonth(month,day)},rate=goalRate(s,g.total),tx=txForDate(date),rawGoal=data.dailyGoals[date],origin=rawGoal?.origin==='daily'?'当日目標として固定':rawGoal?.origin==='monthly'||Number(monthlyGoal(month).daily?.[day])>0?'月間計画から設定':'未設定',variance=g.total?s-g.total:0,markers=buildMonthFinancialMarkers(month),marker=markers.get(date)||{},acf=data.acfSettings.initialized?buildCashFlowForecast():null,acfRow=acf?.rows.find(r=>r.date===date),large=marker.largePlans||[],fixed=marker.fixedPayments||[],salaries=marker.salaries||[],cards=marker.cardPayments||[];
  pushView('その日の資金詳細',`<div class="section-head" style="margin-top:2px">${dayLabel(date)}</div><div class="hero"><div class="daily-goal"><div class="ring"><svg viewBox="0 0 154 154"><circle class="track" cx="77" cy="77" r="60"></circle><circle class="progress ${rate>100?'over':''}" cx="77" cy="77" r="60" stroke-dasharray="${2*Math.PI*60}" stroke-dashoffset="${2*Math.PI*60*(1-clamp(rate,0,100)/100)}"></circle></svg><div class="ring-center"><div class="ring-amount">${yen(s)}</div><div class="ring-caption">実質支出</div></div></div><div><div class="goal-side-title">目標</div><div class="goal-side-value">${g.total?yen(g.total):'未設定'}</div><div class="goal-rate">${g.total?rate+'%':'—'}</div></div></div></div>${dayClosingCardHtml(date,'inspectDayClose')}<div class="section-head">計画とACF</div><div class="group"><button type="button" class="row press" id="dayGoalDetail"><div class="row-main"><div class="row-title">当日の目標</div><div class="row-sub">${origin}</div></div><div class="row-value">${g.total?yen(g.total):'未設定'}</div><span class="chev">›</span></button>${g.total?`<div class="row"><div class="row-main"><div class="row-title">計画との差異</div><div class="row-sub">月末ACFへの概算影響 ${variance>0?'−':'+'}${yen(Math.abs(variance))}</div></div><div class="row-value ${variance>0?'red':variance<0?'green':''}">${variance>0?'+':''}${yen(variance)}</div></div>`:''}${acfRow?`<div class="row"><div class="row-main"><div class="row-title">安全に使える</div><div class="row-sub">現金 ${yen(acfRow.safeCashBudget||0)}・カード ${yen(acfRow.safeCreditBudget||0)}</div></div><div class="row-value">${yen(acfRow.safeTotalBudget||0)}</div></div><div class="row"><div class="row-main"><div class="row-title">カードを含めた最大額</div><div class="row-sub">登録済み予定と安全残高を考慮</div></div><div class="row-value">${yen(acfRow.maxSpendCombined||0)}</div></div>`:''}</div>${salaries.length?`<div class="section-head">給与予定</div><div class="group">${salaries.map(x=>`<div class="row"><div class="row-main"><div class="row-title">${esc(x.employerName)}</div><div class="row-sub">${x.workMonth?`${Number(x.workMonth.slice(5,7))}月勤務分・`:''}${x.status}</div></div><div class="row-value green">+${yen(x.amount)}</div></div>`).join('')}</div>`:''}${cards.length?`<div class="section-head">カード引落予定</div><div class="group">${cards.map(x=>`<div class="row"><div class="row-main"><div class="row-title">${esc(x.cardName)}</div><div class="row-sub">${Number(x.billingMonth.slice(5,7))}月請求</div></div><div class="row-value">${yen(x.amount)}</div></div>`).join('')}<div class="row"><div class="row-main"><div class="row-title">合計</div></div><div class="row-value">${yen(sum(cards,x=>x.amount))}</div></div></div>`:''}${fixed.length?`<div class="section-head">固定支払い</div><div class="group">${fixed.map(x=>`<div class="row"><div class="row-main"><div class="row-title">${esc(x.name)}</div></div><div class="row-value">${yen(x.amount)}</div></div>`).join('')}</div>`:''}${large.length?`<div class="section-head">大型支出計画</div><div class="group">${large.map(x=>`<button type="button" class="row press" data-inspect-large="${x.id}"><span class="large-plan-badge ${x.priority==='optional'?'optional':''}"></span><div class="row-main"><div class="row-title">${esc(x.name)}</div><div class="row-sub">${x.priority==='required'?'必須':'検討中'}・${esc(largeExpensePaymentLabel(x))}</div></div><div class="row-value">${yen(x.amount)}</div><span class="chev">›</span></button>`).join('')}</div>`:''}<div class="day-inspector-actions"><button type="button" class="secondary" id="inspectExpense">支出を追加</button><button type="button" class="secondary" id="inspectPlan">計画を変更</button><button type="button" class="secondary" id="inspectWhatIf">もし使ったら？</button><button type="button" class="secondary" id="inspectLarge">大型支出を追加</button></div><div class="section-head">支出履歴</div>${tx.length?`<div class="group">${tx.map(t=>`<button type="button" class="row press" data-inspect-tx="${t.id}"><div class="row-main"><div class="row-title">${esc(t.merchant)}</div><div class="row-sub">${esc(t.category)}・${esc(paymentLabel(t))}</div></div><div class="row-value">${yen(t.amount)}</div><span class="chev">›</span></button>`).join('')}</div>`:'<div class="empty">支出記録はありません。</div>'}`,root=>{
    root.querySelector('#inspectDayClose')?.addEventListener('click',()=>openDayClosing(date));
    root.querySelector('#dayGoalDetail').onclick=()=>openDailyGoalPlanner(date);
    root.querySelector('#inspectExpense').onclick=()=>openQuickExpense(date);
    root.querySelector('#inspectPlan').onclick=()=>openDayPlanSheet(date);
    root.querySelector('#inspectWhatIf').onclick=()=>openAcfSimulator(date);
    root.querySelector('#inspectLarge').onclick=()=>openLargeExpenseEditor(null,{after:()=>renderAll()});
    root.querySelectorAll('[data-inspect-large]').forEach(b=>b.onclick=()=>openLargeExpenseDetail(b.dataset.inspectLarge));
    root.querySelectorAll('[data-inspect-tx]').forEach(b=>b.onclick=()=>openTransactionDetail(b.dataset.inspectTx))
  })
}

